import{_ as r,I as d,c as o,o as n,j as e,J as i,a5 as s,a as l}from"./chunks/framework.CUJoMJm2.js";const g=JSON.parse('{"title":"Threat Model","description":"","frontmatter":{},"headers":[],"relativePath":"protocols/sbrp/threat-model.md","filePath":"protocols/sbrp/threat-model.md","lastUpdated":0}'),c={name:"protocols/sbrp/threat-model.md"};function h(m,t,p,u,y,b){const a=d("CopyOrDownloadAsMarkdownButtons");return n(),o("div",null,[t[0]||(t[0]=e("div",{style:{display:"none"},hidden:"true","aria-hidden":"true"},"Are you an LLM? You can read better optimized documentation at /protocols/sbrp/threat-model.md for this page in Markdown format",-1)),t[1]||(t[1]=e("h1",{id:"threat-model",tabindex:"-1"},[l("Threat Model "),e("a",{class:"header-anchor",href:"#threat-model","aria-label":"Permalink to “Threat Model”"},"​")],-1)),i(a),t[2]||(t[2]=s('<blockquote><p><strong>Authority</strong>: Primary (Normative)<br><strong>Purpose</strong>: Defines attacker model, trust boundaries, and security assumptions for SBRP.</p></blockquote><h2 id="attacker-model" tabindex="-1">Attacker Model <a class="header-anchor" href="#attacker-model" aria-label="Permalink to “Attacker Model”">​</a></h2><p>SBRP considers three attacker types with progressively stronger capabilities:</p><ol><li><strong>Network attacker</strong>: Can observe, modify, delay, or drop traffic between any endpoints</li><li><strong>Compromised relay</strong>: Has full control of the relay server, including routing and metadata</li><li><strong>Compromised control plane</strong>: Can issue arbitrary tokens, forge user authorization</li></ol><h2 id="trust-boundaries" tabindex="-1">Trust Boundaries <a class="header-anchor" href="#trust-boundaries" aria-label="Permalink to “Trust Boundaries”">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Trust Level</th><th>Compromise Impact</th></tr></thead><tbody><tr><td>Relay auth</td><td>Trusted</td><td>Can deny service, can&#39;t decrypt</td></tr><tr><td>Relay transport</td><td>Honest-but-curious</td><td>Sees encrypted blobs only</td></tr><tr><td>Client runtime</td><td>Trusted</td><td>Full compromise (inherent to web for browsers)</td></tr><tr><td>Daemon</td><td>Trusted</td><td>Full compromise</td></tr></tbody></table><h2 id="threat-mitigations" tabindex="-1">Threat Mitigations <a class="header-anchor" href="#threat-mitigations" aria-label="Permalink to “Threat Mitigations”">​</a></h2><table tabindex="0"><thead><tr><th>Threat</th><th>Attacker</th><th>Mitigation</th><th>Result</th></tr></thead><tbody><tr><td>Read messages</td><td>Relay</td><td>ChaCha20-Poly1305</td><td>Cannot decrypt</td></tr><tr><td>MITM handshake</td><td>Relay</td><td>Ed25519 signatures + TOFU pinning</td><td>Cannot forge (after first connection)</td></tr><tr><td>Key substitution</td><td>Relay</td><td>TOFU identity pinning</td><td>Detected on subsequent connections</td></tr><tr><td>Replay messages</td><td>Network</td><td>Bitmap sequence window</td><td>Rejected</td></tr><tr><td>Impersonate daemon</td><td>Relay</td><td>No private key access</td><td>Cannot sign</td></tr><tr><td>Cross-daemon confusion</td><td>Relay</td><td>daemonId in signature payload</td><td>Rejected</td></tr><tr><td>Deny service</td><td>Relay</td><td>N/A</td><td>Accepted risk</td></tr></tbody></table><h2 id="attack-resistance" tabindex="-1">Attack Resistance <a class="header-anchor" href="#attack-resistance" aria-label="Permalink to “Attack Resistance”">​</a></h2><table tabindex="0"><thead><tr><th>Attack</th><th>Mitigation</th></tr></thead><tbody><tr><td>Relay reads messages</td><td>E2EE encryption</td></tr><tr><td>Relay MITM</td><td>Ed25519 signatures on ephemeral keys</td></tr><tr><td>Replay attack</td><td>Sequence numbers, sliding window</td></tr><tr><td>Reflection attack</td><td>Directional keys</td></tr><tr><td>Key substitution</td><td>Signature binds ephemeral to identity</td></tr><tr><td>Session hijacking</td><td>Token-based auth; relay acts on tokens, cannot verify user intent (see below)</td></tr></tbody></table><h2 id="known-limitations" tabindex="-1">Known Limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to “Known Limitations”">​</a></h2><table tabindex="0"><thead><tr><th>Attack</th><th>Status</th></tr></thead><tbody><tr><td>Compromised relay auth</td><td>Can deny service, can&#39;t decrypt or MITM</td></tr><tr><td>Compromised client runtime</td><td>Full compromise (inherent to web apps for browsers)</td></tr><tr><td>Traffic analysis</td><td>Relay sees timing, size, frequency; may infer high-level usage patterns</td></tr><tr><td>Daemon identity key compromise</td><td>Must rotate key, re-register</td></tr><tr><td>Relay user impersonation</td><td>Relay cannot verify user actually requested the session; client is not cryptographically authenticated to daemon</td></tr></tbody></table><h2 id="assumptions" tabindex="-1">Assumptions <a class="header-anchor" href="#assumptions" aria-label="Permalink to “Assumptions”">​</a></h2><ul><li>TLS between all WebSocket endpoints (browser-relay, daemon-relay)</li><li>Control plane is trusted for initial key distribution (TOFU limitation)</li><li>Daemon private keys are stored securely (file permissions <code>0600</code>)</li><li>Clients implement durable TOFU key pinning (IndexedDB or equivalent)</li><li>Replay window is implemented correctly (bitmap-based, at least 64 messages)</li></ul>',14))])}const f=r(c,[["render",h]]);export{g as __pageData,f as default};
